{"python":"def pilot_policy(trace):
    if not trace:
        return
    action, label = trace[-1]
    args = json.loads(action.arguments)

    policy_dict = {"slot:courier": ["PHI"], "slot:debug": ["PHI", "POLICY_ID"]}

    if action.name == "sender/submit":
        target = args.get("target")
        receipt = args.get("receipt")
        if receipt == "verbose":
            allowed_debug = policy_dict.get("slot:debug")
            if allowed_debug and not label.subset.issubset(set(allowed_debug)):
                raise PolicyViolation("Label subset not allowed at debug platform")
            if target == "courier":
                allowed_courier = policy_dict.get("slot:courier")
                if allowed_courier and not label.subset.issubset(set(allowed_courier)):
                    raise PolicyViolation("Label subset not allowed at courier")
        else:
            if target == "courier":
                allowed_courier = policy_dict.get("slot:courier")
                if allowed_courier and not label.subset.issubset(set(allowed_courier)):
                    raise PolicyViolation("Label subset not allowed at courier")
    elif action.name == "sender/receipt":
        target = args.get("target")
        if target == "debug":
            allowed_debug = policy_dict.get("slot:debug")
            if allowed_debug and not label.subset.issubset(set(allowed_debug)):
                raise PolicyViolation("Label subset not allowed at debug platform")
    return"}
